import{_ as a,o as s,c as i,a2 as t}from"./chunks/framework.BXzK3EA4.js";const g=JSON.parse('{"title":"Day 7: Custom Image Recipes & Image Features","description":"","frontmatter":{},"headers":[],"relativePath":"day7-custom-image-recipes-and-features.md","filePath":"day7-custom-image-recipes-and-features.md"}'),o={name:"day7-custom-image-recipes-and-features.md"};function n(r,e,l,d,c,p){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="day-7-custom-image-recipes-image-features" tabindex="-1">Day 7: Custom Image Recipes &amp; Image Features <a class="header-anchor" href="#day-7-custom-image-recipes-image-features" aria-label="Permalink to &quot;Day 7: Custom Image Recipes &amp; Image Features&quot;">​</a></h1><div style="background:linear-gradient(135deg, #11998e 0%, #38ef7d 100%);padding:1.5rem;border-radius:12px;margin-bottom:2rem;color:white;"><p><strong>🎯 Learning Objectives</strong></p><p>By the end of this module, you will be able to:</p><ol><li>Inherit <code>core-image</code> to create a custom image recipe instead of appending to <code>local.conf</code></li><li>Group software using package groups and standard Yocto conventions</li><li>Utilize <code>IMAGE_FEATURES</code> to easily enable high-level functionalities like SSH servers</li><li>Generate and inspect <code>.manifest</code> files to audit installed packages</li><li>Define default passwords or SSH root access for development images</li></ol></div><div class="info custom-block"><p class="custom-block-title">PREREQUISITES</p><ul><li>Completed <a href="/day6-bitbake-operators-and-layer-creation.html">Day 6: BitBake Operators &amp; Layer Creation</a></li><li>Created the <code>meta-custom</code> layer from the previous lab</li></ul></div><hr><h2 id="_1-why-create-a-custom-image-recipe" tabindex="-1">1. Why Create a Custom Image Recipe? <a class="header-anchor" href="#_1-why-create-a-custom-image-recipe" aria-label="Permalink to &quot;1. Why Create a Custom Image Recipe?&quot;">​</a></h2><p>Up to this point, we have built the default <code>core-image-minimal</code> provided by OE-Core, and to add packages, we modified <code>IMAGE_INSTALL:append</code> in <code>local.conf</code>.</p><p><strong>This is an anti-pattern for production!</strong><code>local.conf</code> is designed for <em>local build machine settings</em> (like CPU cores, downloads directories, and target machine), not for defining the contents of the final product.</p><p>If you commit your project to Git, <code>local.conf</code> is usually ignored (via <code>.gitignore</code>), meaning other developers won&#39;t get your package additions. The correct approach is to create a custom <strong>Image Recipe</strong> inside your custom layer.</p><hr><h2 id="_2-writing-a-custom-image-recipe" tabindex="-1">2. Writing a Custom Image Recipe <a class="header-anchor" href="#_2-writing-a-custom-image-recipe" aria-label="Permalink to &quot;2. Writing a Custom Image Recipe&quot;">​</a></h2><p>Let&#39;s create a custom image that includes a text editor (<code>nano</code>), network tools (<code>curl</code>), and an SSH server.</p><p>Create a new file in your layer: <code>meta-custom/recipes-core/images/my-custom-image.bb</code></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SUMMARY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;My Custom Embedded Linux Distribution&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">DESCRIPTION</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;A production-ready image based on core-image-minimal but with networking and debug tools.&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Inherit the base image logic from OE-Core</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">inherit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> core-image</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Add our custom packages to the root filesystem</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">IMAGE_INSTALL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    nano </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    curl </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    iproute2 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Enable high-level image features</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">IMAGE_FEATURES</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    ssh-server-dropbear </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    debug-tweaks </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><h3 id="building-your-image" tabindex="-1">Building Your Image <a class="header-anchor" href="#building-your-image" aria-label="Permalink to &quot;Building Your Image&quot;">​</a></h3><p>Instead of building <code>core-image-minimal</code>, you now instruct BitBake to build your new recipe:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bitbake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-custom-image</span></span></code></pre></div><hr><h2 id="_3-the-power-of-image-features" tabindex="-1">3. The Power of <code>IMAGE_FEATURES</code> <a class="header-anchor" href="#_3-the-power-of-image-features" aria-label="Permalink to &quot;3. The Power of \`IMAGE_FEATURES\`&quot;">​</a></h2><p>The <code>IMAGE_FEATURES</code> variable allows you to enable broad classes of functionality without having to know the names of the individual underlying packages. The <code>core-image</code> class translates these features into the correct <code>IMAGE_INSTALL</code> lists.</p><table tabindex="0"><thead><tr><th>Feature</th><th>Description</th></tr></thead><tbody><tr><td><code>ssh-server-dropbear</code></td><td>Installs the lightweight Dropbear SSH server.</td></tr><tr><td><code>ssh-server-openssh</code></td><td>Installs the full OpenSSH server suite.</td></tr><tr><td><code>x11-base</code></td><td>Installs a basic X11 graphical server.</td></tr><tr><td><code>tools-debug</code></td><td>Installs gdb, strace, and other debugging tools.</td></tr><tr><td><code>tools-sdk</code></td><td>Installs a full compiler toolchain (gcc, make) on the target board itself.</td></tr><tr><td><code>debug-tweaks</code></td><td>Crucial for development! Allows passwordless root login (empty password). <strong>Remove this before production!</strong></td></tr></tbody></table><hr><h2 id="_4-package-groups" tabindex="-1">4. Package Groups <a class="header-anchor" href="#_4-package-groups" aria-label="Permalink to &quot;4. Package Groups&quot;">​</a></h2><p>Instead of listing 50 individual networking utilities in <code>IMAGE_INSTALL</code>, Yocto uses <strong>Package Groups</strong> (previously known as tasks). These are meta-packages that depend on a logical grouping of other packages.</p><p>For example, to install a complete suite of networking tools, you can just add:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">IMAGE_INSTALL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;packagegroup-core-full-cmdline&quot;</span></span></code></pre></div><p>You can view the available package groups in <code>meta/recipes-core/packagegroups/</code>.</p><hr><h2 id="_5-security-handling-root-passwords" tabindex="-1">5. Security: Handling Root Passwords <a class="header-anchor" href="#_5-security-handling-root-passwords" aria-label="Permalink to &quot;5. Security: Handling Root Passwords&quot;">​</a></h2><p>By default, Yocto images lock the <code>root</code> account unless <code>debug-tweaks</code> is enabled in <code>IMAGE_FEATURES</code>, which sets an empty password.</p><p>For production, you must remove <code>debug-tweaks</code> and set a secure password. You can do this by inheriting <code>extrausers</code> in your image recipe:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># In your my-custom-image.bb</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">inherit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> extrausers</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Set root password to &quot;root&quot; (hash generated using openssl passwd -6)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">EXTRA_USERS_PARAMS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;usermod -p &#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">6</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">xyz123</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">hashedpasswordstring&#39; root;&quot;</span></span></code></pre></div><hr><h2 id="_6-hands-on-lab-exercises" tabindex="-1">6. Hands-On Lab Exercises <a class="header-anchor" href="#_6-hands-on-lab-exercises" aria-label="Permalink to &quot;6. Hands-On Lab Exercises&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">LAB 7.1: Create Your First Custom Image</p><ol><li>Inside your <code>meta-myproject</code> layer (from Day 6), create the folder structure: <code>mkdir -p recipes-core/images/</code>.</li><li>Create <code>my-custom-image.bb</code> and populate it with <code>nano</code>, <code>htop</code>, and the Dropbear SSH server.</li><li>Build the image: <code>bitbake my-custom-image</code>.</li><li>Run it in QEMU: <code>runqemu qemuarm nographic slirp</code>.</li><li>Verify you can run <code>nano</code> and <code>htop</code> inside QEMU.</li></ol></div><div class="tip custom-block"><p class="custom-block-title">LAB 7.2: Analyzing the Manifest File</p><p>How do you prove to your security team exactly which open-source packages are in your final image? You look at the <code>.manifest</code> file!</p><ol><li>Navigate to <code>tmp/deploy/images/qemuarm/</code>.</li><li>Locate the file ending in <code>.manifest</code> (e.g., <code>my-custom-image-qemuarm.manifest</code>).</li><li>Open it. This file lists every single IPK/RPM package installed in the rootfs along with its exact version architecture. This is critical for SBOM (Software Bill of Materials) generation.</li></ol></div><hr><h2 id="_7-further-reading" tabindex="-1">7. Further Reading <a class="header-anchor" href="#_7-further-reading" aria-label="Permalink to &quot;7. Further Reading&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>URL</th></tr></thead><tbody><tr><td>Customizing Images</td><td><a href="https://docs.yoctoproject.org/dev-manual/customizing-images.html" target="_blank" rel="noreferrer">docs.yoctoproject.org/dev-manual/customizing-images.html</a></td></tr><tr><td>Image Features Reference</td><td><a href="https://docs.yoctoproject.org/ref-manual/features.html#image-features" target="_blank" rel="noreferrer">docs.yoctoproject.org/ref-manual/features.html#image-features</a></td></tr></tbody></table><hr><div style="display:flex;justify-content:space-between;margin-top:2rem;padding-top:1rem;border-top:1px solid #e2e8f0;"><a href="/day6-bitbake-operators-and-layer-creation">← Day 6: BitBake Operators &amp; Layers</a><a href="/day8-writing-recipes-and-c-apps">Day 8: Writing Recipes &amp; C Apps →</a></div>`,40)])])}const u=a(o,[["render",n]]);export{g as __pageData,u as default};
